program.compute:
pool = read('/input/options')
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if valid(current):
        result = current
if result is None:
    write('/output/selection', result)
if receipt('report') == 'success':
    pass
else:
    if receipt('report') == 'unknown':
        status('report')
    if receipt('report') == 'unattempted' or status('report') == 'not_sent':
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

